const input=$json??{};
const dealId=input.deal_id??null; const leadId=input.lead_id??null; const propertyId=input.property_id??null;
const status=String(input.status??'').toLowerCase(); const deliveryStatus=String(input.delivery_status??'').toLowerCase();
const sellerResponse=String(input.seller_response??input.inbound_message??'').trim();
const dnc=Boolean(input.dnc??input.do_not_contact??false); const blockers=Array.isArray(input.blockers)?input.blockers:[];
const attempts=Number(input.reengagement_attempts??input.attempts??0); const maxAttempts=Number(input.max_reengagement_attempts??3);
const sentAt=input.sent_at??input.delivered_at??input.last_outbound_at??null; const timeoutHours=Number(input.response_timeout_hours??24);
const idempotencyKey=String(input.idempotency_key??'').trim();
let route='needs_review'; let action='review'; let nextWorkflow='WF-349'; let reason='Response timeout state requires review.';
if(dnc){route='blocked';action='stop';nextWorkflow='WF-126';reason='DNC protection prevents timeout follow-up.';}
else if(blockers.length){route='blocked';action='stop';nextWorkflow='WF-126';reason='Active blocker prevents timeout follow-up.';}
else if(sellerResponse){route='seller_response_received';action='classify_response';nextWorkflow='WF-342';reason='Seller response received before timeout; route to classification.';}
else if(!dealId||!leadId||!propertyId||!idempotencyKey){route='incomplete';action='repair_data';nextWorkflow='WF-349';reason='Required identity or idempotency data is missing.';}
else if(status==='awaiting_response'||deliveryStatus==='delivered'||deliveryStatus==='delivery_success'||deliveryStatus==='sent'){route='awaiting_response';action='wait_or_timeout';nextWorkflow='WF-351';reason='Outbound message is delivered/accepted; response timeout must be evaluated before follow-up.';}
else if(attempts>=maxAttempts){route='max_attempts_reached';action='pause';nextWorkflow='WF-126';reason='Maximum outreach attempts reached; human review required.';}
else{route='needs_review';action='review';nextWorkflow='WF-349';reason='Current state does not authorize timeout follow-up.';}
const timeoutAt=sentAt?new Date(new Date(sentAt).getTime()+timeoutHours*3600000).toISOString():null;
const activity={activity_type:'seller_response_timeout_controller',subject:'WF-351 '+(dealId??'unknown-deal'),deal_id:dealId,lead_id:leadId,property_id:propertyId,route,action,next_workflow:nextWorkflow,sent_at:sentAt,timeout_hours:timeoutHours,timeout_at:timeoutAt,reengagement_attempts:attempts,max_reengagement_attempts:maxAttempts,idempotency_key:idempotencyKey,dnc,blockers,reason};
return [{json:{...input,wf_id:'WF-351',route,action,next_workflow:nextWorkflow,timeout_hours:timeoutHours,timeout_at:timeoutAt,reason,crm_activity:activity,evaluated_at:new Date().toISOString()}}];
